def zero_memory_gb(params_billion: float, n_gpus: int, stage: int) -> float:
    weights, grads, optim = 2.0, 2.0, 12.0
    if stage >= 1:
        optim /= n_gpus
    if stage >= 2:
        grads /= n_gpus
    if stage >= 3:
        weights /= n_gpus
    return params_billion * (weights + grads + optim)

def min_zero_stage(params_billion: float, n_gpus: int, gpu_gb: float, headroom: float = 0.8) -> int:
    budget = gpu_gb * headroom
    for stage in range(4):
        if zero_memory_gb(params_billion, n_gpus, stage) <= budget:
            return stage
    return -1

print(min_zero_stage(7, 8, 80))
print(min_zero_stage(70, 8, 80))
print(min_zero_stage(1, 4, 24))
print(min_zero_stage(13, 8, 80))
